function slugify(input: string): string {
  return input
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

function hydrate(row: Packed, i: number): Ward {
  return {
    code: i + 1,
    name: row[0],
    slug: slugify(row[0]),
    constituencyCode: row[1],
    countyCode: row[2],
    subCounty: row[3] === -1 ? null : SUB_COUNTIES[row[3]]!,
    aliases: row[4] ?? [],
  }
}

export const wards: readonly Ward[] = packed.map(hydrate)
